entries[414293] = { ["name"] = "Zeitlinientranszendenz", ["text"] = "Kanalisiert (Wirken in 7 tagen)\nChromie erschafft eine Zeitverzerrungsblase, die Spielercharakteren ihr maximales zukünftiges Potenzial gewährt.\n\nErhöht den verursachten Schaden um 100%, das Tempo um 100%, die Abklingzeitrate um 100% und die Ressourcenregenerationsrate um 100.\n\nChromie kann dies nur einmal tun, ohne eine dauerhafte Konvergenz der Zeitlinien zu riskieren." }
