entries[414316] = { ["name"] = "Weißer Kriegswolf", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren weißen Kriegswolf oder gibt ihn wieder frei.\n\"Kann der Hunger eines Wolfs je gestillt werden? Diese Wolfsbestien suchen und verschlingen die Feinde der Horde.\"\nHorde\nBeute von:\nZeitrisse\nVerkäufer:\nWächterin Krizzik\nZone:\nTyrholdreservoir\nKosten:\n3.000\n\nAllianz\nGegenstand:\nGeschenk des weißen Kriegswolfs" }
