entries[414323] = { ["name"] = "Hungriger schwarzer Greif", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Der Krieg hat diese einst stolzen Kreaturen verdorben. Das Flüstern ihrer Schwingen säuselt jetzt von Omen eines nahenden Untergangs.\"\nAllianz\nBeute von:\nZeitrisse\nVerkäufer:\nWächterin Krizzik\nZone:\nTyrholdreservoir\nKosten:\n3.000\n\nHorde\nGegenstand:\nGeschenk des hungrigen schwarzen Greifen" }
entries[414324] = { ["name"] = "Goldzehenalbatros", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Aus einem fernen Zeitweg emporgestiegen, wurde dieser noch nie gesehene Vertreter der Vögel in einer geordneten Welt geboren.\"\nBeute von:\nZeitrisse\nVerkäufer:\nSorotis\nZone:\nTyrholdreservoir\nKosten:\n3.000" }
entries[414326] = { ["name"] = "Teufelssturmdrache", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Die Brennende Legion besiegte Drachen in einem fernen Zeitweg. Diese üblen Teufelswyrms wählten Verderbnis und Knechtschaft, um der Vernichtung zu entgehen.\"\nBeute von:\nZeitrisse\nVerkäufer:\nFalara Nachtweise\nZone:\nTyrholdreservoir\nKosten:\n3.000" }
entries[414327] = { ["name"] = "Schwefelhund", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren Schwefelhund oder gibt ihn wieder frei.\n\"Das Schwarze Imperium unterwarf diese demütigen und hasserfüllten Hunde. Grenzenlos unterwürfig dienen sie noch immer den Starken.\"\nBeute von:\nZeitrisse\nVerkäufer:\nVersorgerin Qorra\nZone:\nTyrholdreservoir\nKosten:\n3.000" }
entries[414328] = { ["name"] = "Perfektionierter Koloss", ["text"] = "Wirken in 1.5 sek.\nBeschwört den perfektionierten Koloss oder gibt ihn wieder frei.\n\"Wie Schönheit liegt auch Perfektion im Auge des Betrachters. Doch Sehkraft kann chirurgisch verbessert werden.\"\nBeute von:\nZeitrisse\nVerkäufer:\nNora mit dem Bohrer\nZone:\nTyrholdreservoir\nKosten:\n3.000" }
