entries[414564] = { ["name"] = "Verfluchter Stoff", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nKampfzerrissene Fetzen (50), Teufelsstoff (20), Essenz des Untodes (6), Dunkelrune (2), Gefrorene Rune\nDieser verfluchte Gegenstand verbindet sich mit der ersten Seele, mit der er in Berührung kommt, und kann daher nur über einen Handwerksauftrag für andere hergestellt werden.\nEntdeckung:\nNaxxramas\n\nVerfluchter Stoff\nWird beim Aufheben gebunden\nBenutzen: Repariert ein Ausrüstungsteil des beklagten Kreuzfahrers mit verderbten Materialien und stellt so einen Teil seiner früheren Pracht wieder her.\n\nDer so entstandene Gegenstand wird kriegsmeutengebunden und die Entweihung kann von einem Magier, Priester oder Hexenmeister geläutert werden, der gewillt ist, die nötigen Reagenzien zu beschaffen." }
entries[414565] = { ["name"] = "Ermattetes Leder", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nKampfzerrissene Fetzen (50), Verzaubertes Leder (40), Essenz des Untodes (6), Dunkelrune (2), Gefrorene Rune\nDieser verfluchte Gegenstand verbindet sich mit der ersten Seele, mit der er in Berührung kommt, und kann daher nur über einen Handwerksauftrag für andere hergestellt werden.\nEntdeckung:\nNaxxramas\n\nErmattetes Leder\nWird beim Aufheben gebunden\nBenutzen: Repariert ein Ausrüstungsteil des beklagten Kreuzfahrers mit verderbten Materialien und stellt so einen Teil seiner früheren Pracht wieder her.\n\nDer so entstandene Gegenstand wird kriegsmeutengebunden und die Entweihung kann von einem Druiden oder Schurken geläutert werden, der gewillt ist, die nötigen Reagenzien zu beschaffen." }
entries[414566] = { ["name"] = "Verseuchte Schuppen", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nKampfzerrissene Fetzen (50), Verzaubertes Leder (40), Essenz des Untodes (6), Dunkelrune (2), Gefrorene Rune\nDieser verfluchte Gegenstand verbindet sich mit der ersten Seele, mit der er in Berührung kommt, und kann daher nur über einen Handwerksauftrag für andere hergestellt werden.\nEntdeckung:\nNaxxramas\n\nVerseuchte Schuppen\nWird beim Aufheben gebunden\nBenutzen: Repariert ein Ausrüstungsteil des beklagten Kreuzfahrers mit verderbten Materialien und stellt so einen Teil seiner früheren Pracht wieder her.\n\nDer so entstandene Gegenstand wird kriegsmeutengebunden und die Entweihung kann von einem Jäger oder Schamanen geläutert werden, der gewillt ist, die nötigen Reagenzien zu beschaffen." }
entries[414567] = { ["name"] = "Untodesmetall", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nKampfzerrissene Fetzen (50), Arkanitbarren (10), Essenz des Untodes (6), Dunkelrune (2), Gefrorene Rune\nDieser verfluchte Gegenstand verbindet sich mit der ersten Seele, mit der er in Berührung kommt, und kann daher nur über einen Handwerksauftrag für andere hergestellt werden.\nEntdeckung:\nNaxxramas\n\nUntodesmetall\nWird beim Aufheben gebunden\nBenutzen: Repariert ein Ausrüstungsteil des beklagten Kreuzfahrers mit verderbten Materialien und stellt so einen Teil seiner früheren Pracht wieder her.\n\nDer so entstandene Gegenstand wird kriegsmeutengebunden und die Entweihung kann von einem Paladin oder Krieger geläutert werden, der gewillt ist, die nötigen Reagenzien zu beschaffen." }
