entries[414593] = { ["name"] = "Lichtschimmer", ["text"] = "Sofort\n'Heiliger Schock' hinterlässt für 30 Sek. einen Lichtschimmer auf dem Ziel. Wenn Ihr 'Heiliger Schock' einsetzt, erleiden alle mit 'Lichtschimmer' belegten Ziele (118.272% der Zaubermacht) Schaden oder sie werden um (110% der Zaubermacht) Gesundheit geheilt. Heilung und Schaden von 'Lichtschimmer' erhöhen sich mit jedem zusätzlichen betroffenen Ziel um 6%, werden aber gleichmäßig auf die Ziele aufgeteilt.\n\nIhr könnt bis zu 3 Ziele mit 'Lichtschimmer' belegen." }
