entries[414604] = { ["name"] = "Steinbrecherbeschuss", ["text"] = "Unbegrenzte Reichweite\nSofort\nIridikron greift Chromie 2 Sek. lang mit einem Steinbeschuss an.\n\nJeder Stein verursacht in einem Umkreis von 7 Metern 14546696 Naturschaden, der gleichmäßig auf Chromie und getroffene Spielercharaktere aufgeteilt wird.\n\nWenn ein Spielercharakter einen Stein nicht vor dem Einschlag abfangen kann, löst er ' Steinbrecher ' aus. Abgefangene Steine verursachen 18183370 körperlichen Schaden." }
