entries[414660] = { ["name"] = "Massenbarriere", ["text"] = "8% von Grundmana\nSofort 3 min Abklingzeit\nFrost\nSetzt 'Eisbarriere' bei Euch und 4 Verbündeten innerhalb von 40 Metern ein.\n\nFeuer\nSetzt 'Lodernde Barriere' bei Euch und 4 Verbündeten innerhalb von 40 Metern ein.\n\nArkan\nSetzt 'Prismatische Barriere' bei Euch und 4 Verbündeten innerhalb von 40 Metern ein." }
entries[414661] = { ["name"] = "Eisbarriere", ["text"] = "Sofort\nUmhüllt Euch für 1 Min. mit Eis, das [24 / 100 * Gesamtgesundheit * (1 + Vielseitigkeit)] Schaden absorbiert [ Gletscherpanzer : und Eure Rüstung um 0% erhöht ].\n\nNahkampfangriffe gegen Euch verringern die Bewegungsgeschwindigkeit des Angreifers um 50%." }
entries[414662] = { ["name"] = "Lodernde Barriere", ["text"] = "3% von Grundmana\nSofort\nUmhüllt Euch für 1 Min. mit Flammen, die [20 / 100 * Gesamtgesundheit * (1 + Vielseitigkeit)] Schaden absorbieren [ Geschmolzene Haut : und den erlittenen körperlichen Schaden um 0% verringern ].\n\nNahkampfangriffe gegen Euch fügen dem Angreifer (14.375% der Zaubermacht) Feuerschaden zu." }
entries[414663] = { ["name"] = "Prismatische Barriere", ["text"] = "3% von Grundmana\nSofort\nUmhüllt Euch für 1 Min. mit einem arkanen Schild, der [20 / 100 * Gesamtgesundheit * (1 + Vielseitigkeit)] Schaden absorbiert und den erlittenen Magieschaden um 15% verringert.\n\nDie Dauer aller schädlichen Magieeffekte gegen Euch wird um 25% verringert." }
entries[414664] = { ["name"] = "Massenunsichtbarkeit", ["text"] = "6% von Grundmana\nSofort 5 min Abklingzeit\nIhr und Eure Verbündeten innerhalb von 40 Metern werdet sofort für 12 Sek. unsichtbar. Jegliche Aktion hebt den Effekt auf.\n\nWirkt sich nicht auf Verbündete aus, die in einen Kampf verwickelt sind." }
